"""FastAPI application entrypoint, middleware registration, and API routes."""

from contextlib import asynccontextmanager
from fastapi import FastAPI, Request, status, Depends
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse, RedirectResponse
from app.config import get_settings
from app.database import init_db, check_db_health
from app.logging import LoggingMiddleware, setup_logging
from app.rate_limiter import get_rate_limiter, get_client_ip, SlidingWindowRateLimiter
from app.schemas import (
    ShortenRequest,
    ShortenResponse,
    AnalyticsResponse,
    HealthResponse,
)
from app.service import (
    LinkService,
    get_link_service,
    InvalidURLError,
    InvalidAliasError,
    InvalidExpirationError,
    AliasAlreadyExistsError,
    LinkNotFoundError,
    LinkExpiredError,
)


@asynccontextmanager
async def lifespan(app: FastAPI):
    settings = get_settings()
    setup_logging(settings.log_level)
    init_db(settings.database_path)
    yield


app = FastAPI(
    title="URL Shortener Service",
    description="Secure, persistent URL shortener service with SSRF validation and rate limiting.",
    version="1.0.0",
    lifespan=lifespan,
)

# Configure structured logging at module load time
setup_logging(get_settings().log_level)

# Mount structured JSON access logging middleware
app.add_middleware(LoggingMiddleware)


# --- Exception Handlers ---


@app.exception_handler(RequestValidationError)
async def request_validation_error_handler(request: Request, exc: RequestValidationError):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"detail": "Invalid request payload", "errors": exc.errors()},
    )


@app.exception_handler(InvalidURLError)
async def invalid_url_handler(request: Request, exc: InvalidURLError):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"detail": str(exc)},
    )


@app.exception_handler(InvalidAliasError)
async def invalid_alias_handler(request: Request, exc: InvalidAliasError):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"detail": str(exc)},
    )


@app.exception_handler(InvalidExpirationError)
async def invalid_expiration_handler(request: Request, exc: InvalidExpirationError):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"detail": str(exc)},
    )


@app.exception_handler(AliasAlreadyExistsError)
async def alias_exists_handler(request: Request, exc: AliasAlreadyExistsError):
    return JSONResponse(
        status_code=status.HTTP_409_CONFLICT,
        content={"detail": str(exc)},
    )


@app.exception_handler(LinkNotFoundError)
async def link_not_found_handler(request: Request, exc: LinkNotFoundError):
    return JSONResponse(
        status_code=status.HTTP_404_NOT_FOUND,
        content={"detail": str(exc)},
    )


@app.exception_handler(LinkExpiredError)
async def link_expired_handler(request: Request, exc: LinkExpiredError):
    return JSONResponse(
        status_code=status.HTTP_404_NOT_FOUND,
        content={"detail": str(exc)},
    )


# --- Endpoints ---


@app.post(
    "/shorten",
    response_model=ShortenResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Create a shortened link",
)
async def shorten_url(
    payload: ShortenRequest,
    request: Request,
    service: LinkService = Depends(get_link_service),
    limiter: SlidingWindowRateLimiter = Depends(get_rate_limiter),
):
    client_ip = get_client_ip(request)
    allowed, retry_after = limiter.is_allowed(client_ip)
    if not allowed:
        return JSONResponse(
            status_code=status.HTTP_429_TOO_MANY_REQUESTS,
            content={"detail": "Rate limit exceeded. Try again later."},
            headers={"Retry-After": str(retry_after)},
        )

    result = service.create_link(
        url=payload.url,
        alias=payload.alias,
        expires_at=payload.expires_at,
    )
    return ShortenResponse(**result)


@app.get(
    "/health",
    response_model=HealthResponse,
    status_code=status.HTTP_200_OK,
    summary="Service health check",
)
async def health_check(service: LinkService = Depends(get_link_service)):
    settings = get_settings()
    try:
        is_healthy = check_db_health(settings.database_path) and service.health_check()
    except Exception:
        is_healthy = False

    if is_healthy:
        return HealthResponse(status="healthy")
    return JSONResponse(
        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
        content={"status": "unhealthy"},
    )


@app.get(
    "/analytics/{code}",
    response_model=AnalyticsResponse,
    status_code=status.HTTP_200_OK,
    summary="Get link analytics",
)
async def get_analytics(
    code: str,
    service: LinkService = Depends(get_link_service),
):
    data = service.get_analytics(code)
    return AnalyticsResponse(**data)


@app.get(
    "/{code}",
    status_code=status.HTTP_302_FOUND,
    summary="Redirect to target destination URL",
)
async def redirect_code(
    code: str,
    service: LinkService = Depends(get_link_service),
):
    target_url = service.get_destination_url(code)
    return RedirectResponse(url=target_url, status_code=status.HTTP_302_FOUND)

