"""Pydantic request and response schemas."""

import re
from datetime import datetime
from typing import Optional
from pydantic import BaseModel, Field, field_validator


ALIAS_REGEX = re.compile(r"^[a-zA-Z0-9_-]{3,64}$ ".strip())


class ShortenRequest(BaseModel):
    url: str = Field(..., description="Original destination URL to shorten.")
    alias: Optional[str] = Field(
        default=None,
        description="Optional custom code alias matching ^[a-zA-Z0-9_-]{3,64}$.",
    )
    expires_at: Optional[datetime] = Field(
        default=None,
        description="Optional expiration timestamp in ISO 8601 format.",
    )

    @field_validator("alias")
    @classmethod
    def validate_alias_field(cls, value: Optional[str]) -> Optional[str]:
        if value is not None:
            if not ALIAS_REGEX.match(value):
                raise ValueError(
                    "Custom alias must match pattern ^[a-zA-Z0-9_-]{3,64}$"
                )
        return value


class ShortenResponse(BaseModel):
    code: str
    short_url: str
    original_url: str
    created_at: str
    expires_at: Optional[str] = None


class AnalyticsResponse(BaseModel):
    code: str
    original_url: str
    total_clicks: int
    created_at: str
    last_visited_at: Optional[str] = None
    expires_at: Optional[str] = None


class HealthResponse(BaseModel):
    status: str

